import assert from 'node:assert/strict';
import fs from 'node:fs';
import {Container, Element, flush} from './test-material-research-ui.mjs';

// Calculation contracts are generated by real NumPy cores on bounded grids;
// UI tests independently assert the production values submitted to the worker.
const data=JSON.parse(fs.readFileSync(new URL('../dist/data/electronic-materials.json',import.meta.url),'utf8'));
const fixtures=JSON.parse(fs.readFileSync(new URL('./fixtures/electronic-materials.json',import.meta.url),'utf8'));
const storage=new Map();
globalThis.localStorage={getItem:key=>storage.get(key)||null,setItem:(key,value)=>storage.set(key,value)};
globalThis.document={createElement:tag=>new Element(tag)};
globalThis.fetch=async url=>({ok:true,json:async()=>structuredClone(data),text:async()=>fs.readFileSync(new URL('../dist/'+String(url).split('?')[0],import.meta.url),'utf8')});
const ui=await import('../dist/electronic-materials-ui.js');
// Use exactly the same cache-busted notebook module as the tested UI.
const uiSource=fs.readFileSync(new URL('../dist/electronic-materials-ui.js',import.meta.url),'utf8');
const notebookPath=uiSource.match(/from '(\.\/material-notebook\.js[^']*)'/)[1];
const notebook=await import(new URL('../dist/'+notebookPath.slice(2),import.meta.url));
const {parseClassroomRoute,buildClassroomHash,classroomPathways}=await import('../dist/classroom-ui.js');
const {knownTool}=await import('../dist/navigation-ui.js');
const calls=[];
const calculate=async(action,input)=>{
 calls.push({action,input:structuredClone(input)});
 let key;
 if(action==='pairing_lab')key=input.model==='kitaev'?(input.chemical_potential===2?'pairingCritical':Math.abs(input.chemical_potential)>2?'pairingTrivial':'pairingKitaev'):(input.pairing==='d+id'?'pairingDid':'pairingSquare');
 else if(action==='shg_lab')key=({gaas:'shgGaas',batio3:'shgBTO',centrosymmetric:'shgZero'})[input.model];
 else if(action==='unfold_lab')key=input.mode==='import'?(input.q===.1?'unfoldImportNearest':'unfoldImport'):input.q===-.375&&input.band===2?'unfoldSelection':({perfect:'unfoldPerfect',vacancy:'unfoldVacancy'})[input.model]||'unfoldImpurity';
 else throw Error('Unexpected electronic action '+action);
 return structuredClone(fixtures.results[key]);
};
const mount=async(selection={},run=calculate)=>{const container=new Container(),downloads=[],navigations=[],locations=[],cancelled=[];await ui.renderElectronicMaterialsView({container,selection,run,download:(body,name,type)=>downloads.push({body,name,type}),cancelRun:()=>cancelled.push(true),onNavigate:r=>navigations.push(r),onLocation:r=>locations.push(r)});return {container,downloads,navigations,locations,cancelled,$:s=>container.querySelector(s)};};
const submit=async view=>{view.$('#em-form').onsubmit({preventDefault(){}});await flush();};
const change=(view,id,value)=>{const e=view.$('#em-'+id);assert.ok(e,'Control '+id+' exists');e.value=String(value);view.$('#em-form').oninput({target:e});};
const select=async(view,id,value)=>{const e=view.$('#em-'+id);assert.ok(e,'Select '+id+' exists');e.value=value;await e.onchange?.({target:e});await flush();};
const graphSafe=(html,label)=>assert.doesNotMatch(html,/NaN|Infinity|undefined/,label);

assert.equal(fixtures.format,'real-python-electronic-materials-fixtures');
assert.equal(fixtures.results.pairingKitaev.summary.topological,true);
assert.equal(fixtures.results.pairingTrivial.summary.topological,false);
assert.equal(fixtures.results.pairingCritical.summary.z2_invariant,null);
assert.equal(fixtures.results.shgZero.scan.maxIntensity,0);
assert.equal(fixtures.results.unfoldVacancy.checks.expectedMomentumWeightSum,.75);
assert.equal(classroomPathways.length,7,'The seven established course pathways remain');
for(const [module,pathway]of [['pairing','spin'],['shg','observables'],['unfold','crystal']]){
 const route='compute/'+module+'-lab';
 assert.ok(knownTool(route));
 const parsed=parseClassroomRoute(route+'?material=sample&module=wrong&tab=derive');
 assert.equal(parsed.module,module);assert.equal(parsed.pathway,pathway);assert.equal(parsed.section,'electronic-materials');assert.equal(parsed.tab,'lab');assert.equal(parsed.calculationOnly,true);
 assert.deepEqual(parseClassroomRoute(buildClassroomHash(parsed)),parsed);
 const course=parseClassroomRoute(ui.electronicCourseRoute(module,'tab=derive&material=sample'));
 assert.equal(course.module,module);assert.equal(course.pathway,pathway);assert.equal(course.material,'sample');
 assert.deepEqual(parseClassroomRoute(buildClassroomHash(course)),course);
}
assert.throws(()=>ui.parseElectronicData('[]'),/对象/);
assert.throws(()=>ui.parseElectronicData('{bad'));
assert.throws(()=>ui.parseElectronicData('{"x":"'+'a'.repeat(2_000_001)+'"}'),/2|MB|MiB/);
for(const field of ['real','imag','magnitude','phase'])graphSafe(ui.gapMapSVG(fixtures.results.pairingDid.gap_map,field,fixtures.results.pairingDid.fermi_surface),'Pairing '+field);
for(const name of ['shgGaas','shgBTO','shgZero'])for(const channel of ['PP','PS','SP','SS'])graphSafe(ui.polarSHGSVG(fixtures.results[name].scan,channel,0),'SHG '+name+channel);
graphSafe(ui.unfoldSVG(fixtures.results.unfoldPerfect.unfolded),'Unfolded plot');
graphSafe(ui.unfoldSVG(fixtures.results.unfoldVacancy.folded,false),'Vacancy folded plot');
const merged=ui.unfoldSVG({kOverPi:[0],energies:[[0,0]],weights:[[.3,.7]]});
assert.equal((merged.match(/<circle /g)||[]).length,1,'Degenerate spectral weights are combined into one area');
assert.match(merged,/r="5"/,'A unit combined weight has the full dot area');

const pairing=await mount({calculationOnly:true,module:'pairing'});
assert.equal(pairing.$('#em-preset').value,'','Defaults are not mislabeled as an unselected preset');
assert.equal(pairing.$('#em-hopping').attributes.max,'5');
await submit(pairing);
assert.equal(calls.at(-1).action,'pairing_lab');
assert.equal(calls.at(-1).input.chemical_potential,-1);
assert.equal(calls.at(-1).input.gap,.4);
assert.equal(calls.at(-1).input.grid,41);
assert.equal(calls.at(-1).input.path_samples,61);
assert.equal(calls.at(-1).input.pairing,'d_x2_y2');
assert.ok(pairing.$('#em-gap-map').querySelector('svg'));
graphSafe(pairing.$('#em-gap-map').innerHTML,'Default gap map');
const originalGap=pairing.$('#em-gap-map').innerHTML;
await select(pairing,'field','magnitude');
assert.notEqual(pairing.$('#em-gap-map').innerHTML,originalGap);
assert.equal(ui.getElectronicMaterialsResult().input.pairing,'d_x2_y2','View field does not invalidate the calculation');
change(pairing,'pairing','d+id');await submit(pairing);
assert.equal(ui.getElectronicMaterialsResult().result.parameters.pairing,'d+id');
await select(pairing,'field','phase');graphSafe(pairing.$('#em-gap-map').innerHTML,'Complex gap phase');
await select(pairing,'model','kitaev');assert.equal(ui.getElectronicMaterialsResult(),null);
change(pairing,'chemical_potential',0);await submit(pairing);
assert.ok(pairing.$('#em-chain').querySelector('svg'));
assert.ok((pairing.$('#em-chain').innerHTML.match(/<polyline/g)||[]).length>0,'Open chain has actual weight curves');
graphSafe(pairing.$('#em-chain').innerHTML,'Kitaev chain');
change(pairing,'chemical_potential',3);await submit(pairing);assert.equal(ui.getElectronicMaterialsResult().result.summary.topological,false);
change(pairing,'chemical_potential',2);await submit(pairing);assert.equal(ui.getElectronicMaterialsResult().result.summary.z2_invariant,null);
assert.match(pairing.$('#em-result').innerHTML,/相界|闭合/);

const shg=await mount({calculationOnly:true,module:'shg'});await submit(shg);
assert.equal(calls.at(-1).input.samples,181);assert.deepEqual(calls.at(-1).input.coefficients,{xyz:1});
assert.ok(shg.$('#em-polar').querySelector('svg'));
const firstPolar=shg.$('#em-polar').innerHTML;
shg.$('#em-view-angle').oninput({target:{value:'90'}});
assert.notEqual(shg.$('#em-polar').innerHTML,firstPolar);
assert.match(shg.$('#em-selection').textContent,/90°/);
await select(shg,'view-channel','SP');assert.match(shg.$('#em-selection').textContent,/SP/);
assert.equal(ui.getElectronicMaterialsResult().input.azimuth,30,'View cursor does not silently alter the recorded input');
await select(shg,'model','batio3');assert.deepEqual(JSON.parse(shg.$('#em-coefficients').value),{xxz:1,zxx:.7,zzz:1.5});
await select(shg,'cut','111');assert.ok(shg.$('#em-cOverA'));change(shg,'cOverA',1.01);await submit(shg);
assert.equal(calls.at(-1).input.cOverA,1.01);assert.equal(ui.getElectronicMaterialsResult().result.tensor.dimension,3);
await select(shg,'model','centrosymmetric');
// Switching away from tetragonal geometry must restore cubic c/a=1.
assert.equal(Number(shg.$('#em-cOverA')?.value||1),1);
await submit(shg);assert.equal(ui.getElectronicMaterialsResult().result.scan.maxIntensity,0);
graphSafe(shg.$('#em-polar').innerHTML,'Zero SHG signal');
change(shg,'coefficients','{bad');await submit(shg);assert.equal(ui.getElectronicMaterialsResult(),null);
assert.equal(shg.$('#em-polar'),null);

const unfold=await mount({calculationOnly:true,module:'unfold'});await submit(unfold);
assert.equal(calls.at(-1).input.samples,81);assert.equal(calls.at(-1).input.size,4);assert.equal(calls.at(-1).input.defectStrength,1.5);
assert.ok(unfold.$('#em-result').querySelectorAll('svg').length>=2);
assert.ok(unfold.$('#em-unfold-selection'));
assert.notEqual(unfold.$('#em-cursor').value,'0','The plot cursor starts near the selected primitive momentum');
assert.match(unfold.$('#em-result').innerHTML,/独立求解/);
const beforeCursor=unfold.$('#em-weight-table').innerHTML;
unfold.$('#em-cursor').oninput({target:{value:'3'}});
assert.notEqual(unfold.$('#em-weight-table').innerHTML,beforeCursor);
assert.ok(unfold.$('#em-weight-table').innerHTML.includes(String(Number(fixtures.results.unfoldImpurity.unfolded.kOverPi[3].toPrecision(5)))));
change(unfold,'q',-.375);change(unfold,'band',2);await submit(unfold);
assert.equal(calls.at(-1).input.q,-.375);assert.equal(calls.at(-1).input.band,2);
assert.equal(ui.getElectronicMaterialsResult().result.selection.band,2);
assert.match(unfold.$('#em-unfold-selection').innerHTML,/-0.375/);
assert.ok(unfold.$('#em-unfold-selection').innerHTML.includes(String(Number(fixtures.results.unfoldSelection.selection.energy.toPrecision(5)))));
assert.equal(unfold.$('#em-unfold-selection').querySelectorAll('tbody')[1].querySelectorAll('tr').length,4,'All N unfolding channels are shown');
change(unfold,'q',.25);change(unfold,'band',0);
await select(unfold,'model','vacancy');await submit(unfold);
assert.equal(ui.getElectronicMaterialsResult().result.checks.expectedMomentumWeightSum,.75);
assert.match(unfold.$('#em-result').innerHTML,/0.75|M\/N/);
await select(unfold,'mode','import');await unfold.$('#em-template').onclick();await flush();
assert.equal(JSON.parse(unfold.$('#em-content-json').value).data.schema,'symmetry-lab-unfold-1');
await submit(unfold);assert.equal(calls.at(-1).input.data.phaseConvention,'supercell-bloch');
assert.equal(ui.getElectronicMaterialsResult().result.parameters.mode,'import');
change(unfold,'q',.1);change(unfold,'band',1);await submit(unfold);
assert.equal(ui.getElectronicMaterialsResult().result.selection.requestedQ,.1);
assert.equal(ui.getElectronicMaterialsResult().result.selection.q,0);
assert.match(unfold.$('#em-result').innerHTML,/请求动量未采样/);
assert.match(unfold.$('#em-unfold-selection').innerHTML,/请求 k\/π|实际 k\/π/);
unfold.$('#em-export').onclick();const exported=JSON.parse(unfold.downloads.at(-1).body);
assert.equal(exported.input.data.schema,'symmetry-lab-unfold-1');
assert.equal(exported.result.parameters.mode,'import');
const captured=notebook.latestCalculation();assert.equal(captured.action,'unfold_lab');assert.equal(captured.input.data.schema,'symmetry-lab-unfold-1');
const project=notebook.addRecord(notebook.makeProject({title:'电子材料 UI 检查'}),captured);
assert.equal(notebook.importProject(JSON.stringify(project)).records[0].action,'unfold_lab');
change(unfold,'content-json','{bad');const priorCalls=calls.length;await submit(unfold);
assert.equal(calls.length,priorCalls,'Malformed JSON never reaches Python');assert.equal(ui.getElectronicMaterialsResult(),null);
await unfold.$('#em-file').onchange({target:{files:[{name:'too-large.json',size:2_000_001,text:async()=>'{"x":1}'}]}});await flush();
assert.match(unfold.$('#em-result').textContent,/2|MB|MiB/);
await select(unfold,'mode','model');await select(unfold,'model','perfect');await submit(unfold);
assert.equal(Object.hasOwn(calls.at(-1).input,'data'),false,'Leaving import mode removes hidden imported data');

// A selected preset and a lesson handoff must supply the exact public inputs.
for(const module of data.modules){
 for(const preset of module.presets){
  const v=await mount({calculationOnly:true,module:module.id,preset:preset.id});
  assert.equal(v.$('#em-preset').value,preset.id);
  await submit(v);
  for(const [key,value]of Object.entries(preset.input))assert.deepEqual(calls.at(-1).input[key],value,module.id+' preset '+preset.id+' '+key);
 }
 const l=data.lessons.find(l=>l.module===module.id),v=await mount({module:module.id,lesson:l.id});
 v.$('#em-to-lab').onclick();await submit(v);
 assert.equal(v.$('#em-preset').value,l.preset);
 assert.equal(v.navigations.at(-1).tab,'lab');
}
for(const c of data.cases){
 const v=await mount({calculationOnly:true,module:c.module,material:c.id});await submit(v);
 assert.equal(v.$('#em-preset').value,c.preset);
 assert.equal(notebook.latestCalculation().material,c.id);
 assert.ok(notebook.latestCalculation().route.includes('material='+encodeURIComponent(c.id)));
 const atlas=await mount({atlasOnly:true,module:c.module,material:c.id});
 assert.equal(atlas.$('[data-em-tab]'),null);
 assert.ok(atlas.$('.obs-case-grid'));
 assert.ok(atlas.$('#em-content').innerHTML.includes('material='+encodeURIComponent(c.id)));
 assert.match(atlas.$('#em-content').innerHTML,/#atlas\/notebook/);
}
for(const exercise of data.exercises){
 const v=await mount({module:exercise.module,tab:'derive',exercise:exercise.id});
 let step=v.$('#em-steps').children[0];
 step.querySelector(`[data-em-answer="${(exercise.steps[0].answer+1)%exercise.steps[0].choices.length}"]`).onclick();
 assert.equal(v.$('#em-steps').children.length,1,'Wrong answer does not unlock the next derivation');
 assert.match(step.querySelector('.obs-feedback').textContent,/再想/);
 for(let i=0;i<exercise.steps.length;i++){
  step=v.$('#em-steps').children[i];step.querySelector(`[data-em-answer="${exercise.steps[i].answer}"]`).onclick();
  assert.ok(step.querySelectorAll('button').every(b=>b.disabled));
 }
 assert.equal(JSON.parse(storage.get('symmetry-lab.electronic-materials.progress.v1'))[exercise.id],true);
 assert.match(v.$('#em-progress').textContent,/完成/);
}
assert.ok(Object.keys(notebook.progressSnapshot()).includes('symmetry-lab.electronic-materials.progress.v1'));

let finish;
const stale=await mount({calculationOnly:true,module:'unfold'},()=>new Promise(resolve=>finish=resolve));
stale.$('#em-form').onsubmit({preventDefault(){}});assert.equal(stale.$('#em-run').disabled,true);
change(stale,'q',.1);finish(fixtures.results.unfoldImpurity);await flush();
assert.equal(ui.getElectronicMaterialsResult(),null);assert.equal(stale.cancelled.length,1);
const detached=await mount({calculationOnly:true,module:'pairing'},()=>new Promise(resolve=>finish=resolve));
detached.$('#em-form').onsubmit({preventDefault(){}});detached.container.innerHTML='<p>another route</p>';finish(fixtures.results.pairingSquare);await flush();assert.equal(ui.getElectronicMaterialsResult(),null);
const cancelled=await mount({calculationOnly:true,module:'shg'},()=>new Promise(resolve=>finish=resolve));
cancelled.$('#em-form').onsubmit({preventDefault(){}});cancelled.$('#em-cancel').onclick();finish(fixtures.results.shgGaas);await flush();
assert.equal(cancelled.cancelled.length,1);assert.equal(ui.getElectronicMaterialsResult(),null);assert.equal(cancelled.$('#em-run').disabled,false);
const failure=await mount({calculationOnly:true,module:'pairing'},async()=>{throw Error('<img src=x onerror=alert(1)>');});await submit(failure);
assert.equal(failure.$('#em-result').querySelector('img'),null);assert.match(failure.$('#em-result').textContent,/<img/);assert.equal(ui.getElectronicMaterialsResult(),null);
let resolveFile;
const slow=await mount({calculationOnly:true,module:'unfold'});await select(slow,'mode','import');
slow.$('#em-file').onchange({target:{files:[{name:'older.json',size:100,text:()=>new Promise(resolve=>resolveFile=resolve)}]}});
change(slow,'content-json','{"new":true}');resolveFile('{"older":true}');await flush();
assert.equal(slow.$('#em-content-json').value,'{"new":true}','Typing wins over an older asynchronous file read');
slow.$('#em-file').onchange({target:{files:[{name:'another.json',size:100,text:()=>new Promise(resolve=>resolveFile=resolve)}]}});
await select(slow,'mode','model');resolveFile('{"stale":true}');await flush();
assert.equal(slow.$('#em-content-json'),null,'A late import cannot restore an obsolete source mode');
const loading=await mount({calculationOnly:true,module:'unfold'});await select(loading,'mode','import');
await loading.$('#em-template').onclick();await flush();
loading.$('#em-file').onchange({target:{files:[{name:'pending.json',size:100,text:()=>new Promise(resolve=>resolveFile=resolve)}]}});
assert.equal(loading.$('#em-run').disabled,true,'Run is disabled while a replacement file is being read');
const loadingCalls=calls.length;await submit(loading);assert.equal(calls.length,loadingCalls,'Submitting during file loading cannot calculate the older textarea');
resolveFile(JSON.stringify(fixtures.requests.unfoldImport.input));await flush();
assert.equal(loading.$('#em-run').disabled,false);assert.equal(ui.getElectronicMaterialsResult(),null);
assert.equal(loading.$('#em-result').querySelectorAll('svg').length,0,'A newly loaded file is not displayed beside an older result');
await submit(loading);assert.equal(calls.length,loadingCalls+1);
loading.$('#em-file').onchange({target:{files:[{name:'invalid.json',size:10,text:async()=>'{bad'}]}});await flush();
assert.equal(loading.$('#em-run').disabled,false,'Invalid file parsing releases the loading lock');
assert.equal(ui.getElectronicMaterialsResult(),null);
console.log('Electronic materials UI: real Python fixtures, course/calculation routes, presets, gap/SHG/unfold plots, interactivity, imports, stale result guards, notebook capture/export and every stepwise exercise passed.');
